describe("workspace CLI removal whole original/current caller and native guard", () => {
    it("preserves actual main, captured IDs, claims, reporting and raw faults in source and genuine emission", () => {
        const privateRoot = mkdtempSync(join(tmpdir(), "ccc-cli-removal-"));
        const originalRoot = lstatSync(privateRoot);
        const canonicalRoot = realpathSync(privateRoot);
        const assertOwnedRoot = () => {
            const observed = lstatSync(privateRoot);
            if (!observed.isDirectory() || observed.isSymbolicLink()
                || observed.dev !== originalRoot.dev || observed.ino !== originalRoot.ino
                || observed.uid !== originalRoot.uid || realpathSync(privateRoot) !== canonicalRoot
                || process.getuid && observed.uid !== process.getuid()) {
                throw new Error(`Allocated facade root identity changed: ${privateRoot}`);
            }
        };
        assertOwnedRoot();
        let completed = false;
        let submittedPayload = "";
        let child: SpawnSyncReturns<string> | undefined;
        let retained = false;
        const retain = () => {
            assertOwnedRoot();
            if (retained) return;
            writeFileSync(join(privateRoot, "submitted-stdin.cjs"), submittedPayload, { mode: 0o600, flag: "wx" });
            writeFileSync(join(privateRoot, "child-result.json"), JSON.stringify({
                root: { path: privateRoot, canonicalPath: canonicalRoot, dev: originalRoot.dev, ino: originalRoot.ino, uid: originalRoot.uid },
                stdout: child?.stdout, stderr: child?.stderr, status: child?.status, signal: child?.signal,
                childError: child?.error && { name: child.error.name, message: child.error.message, stack: child.error.stack },
            }, null, 2), { mode: 0o600, flag: "wx" });
            retained = true;
        };
        try {
            // Strict mode precedes every injected declaration; large fixed data
            // goes through owned stdin instead of the operating system argv limit.
            submittedPayload = `'use strict';const ARCHIVE=${JSON.stringify(immutableOriginalClosure)};const PRIVATE_ROOT=${JSON.stringify(privateRoot)};` + controller;
            child = spawnSync(process.execPath, ["--experimental-vm-modules", "-"], {
                cwd: process.cwd(), encoding: "utf8", timeout: 240_000,
                input: submittedPayload, stdio: ["pipe", "pipe", "pipe"],
                env: { PATH: process.env.PATH, HOME: privateRoot, NODE_NO_WARNINGS: "1" },
                maxBuffer: 8 * 1024 * 1024,
            });
            // Preserve the entire submitted input and raw frames before assertions.
            retain();
            expect(child.error).toBeUndefined();
            expect(child.status, child.stderr).toBe(0);
            const report = JSON.parse(child.stdout.trim()) as {
                paired: number; helperChecks: number; managedDefaultChecks: number; unexpectedDenials: number; expectedFenceDenials: number;
                tiers: string[]; guardObservations: number; sameProcessContendersBlocked: number;
                currentClosurePins: { path: string; hash: string }[];
            };
            expect(report.paired).toBe(58);
            expect(report.helperChecks).toBe(29);
            expect(report.managedDefaultChecks).toBe(2);
            expect(report.unexpectedDenials).toBe(0);
            expect(report.expectedFenceDenials).toBe(58 * 4 * 9);
            expect(report.guardObservations).toBe(268);
            expect(report.sameProcessContendersBlocked).toBe(268);
            expect(report.currentClosurePins.some(pin => pin.path === "dist/application/workspace/cli-removal.js")).toBe(true);
            expect(report.tiers).toEqual(["original-source", "original-genuine-emission", "current-source", "current-genuine-emission"]);
            completed = true;
        } catch (error) {
            retain();
            writeFileSync(join(privateRoot, "assertion-error.json"), JSON.stringify(error instanceof Error
                ? { name: error.name, message: error.message, stack: error.stack } : String(error), null, 2), { mode: 0o600, flag: "wx" });
            throw new Error(`Facade failed; complete allocated evidence retained in ${privateRoot}`, { cause: error });
        } finally {
            if (completed) {
                assertOwnedRoot();
                rmSync(privateRoot, { recursive: true, force: true });
            }
        }
    }, 250_000);
});
